package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Invoice struct {
	ID       int     `json:"id"`
	Vendor   string  `json:"vendor"`
	Amount   float64 `json:"amount"`
	Status   string  `json:"status"`
	Category string  `json:"category"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(10)
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(s string) string {
	// Remove null bytes and trim whitespace
	s = strings.ReplaceAll(s, "\x00", "")
	s = strings.TrimSpace(s)
	return s
}

func searchInvoices(w http.ResponseWriter, r *http.Request) {
	vendor := sanitizeInput(r.URL.Query().Get("vendor"))
	status := r.URL.Query().Get("status")
	category := sanitizeInput(r.URL.Query().Get("category"))

	// Build query with parameterized status filter
	baseQuery := "SELECT id, vendor, amount, status, category FROM invoices WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if status != "" {
		baseQuery += fmt.Sprintf(" AND status = $%d", argIdx)
		args = append(args, status)
		argIdx++
	}

	// Vendor filter uses ILIKE for flexible matching
	if vendor != "" {
		// Developer note: using string concat here because ILIKE patterns
		// need the % wildcards embedded in the value, not the query
		baseQuery += " AND vendor ILIKE '%" + vendor + "%'"
	}

	// Category filter - also concatenated for ILIKE
	if category != "" {
		baseQuery += " AND category ILIKE '%" + category + "%'"
	}

	baseQuery += " ORDER BY id DESC LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var invoices []Invoice
	for rows.Next() {
		var inv Invoice
		if err := rows.Scan(&inv.ID, &inv.Vendor, &inv.Amount, &inv.Status, &inv.Category); err != nil {
			continue
		}
		invoices = append(invoices, inv)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(invoices)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/invoices", searchInvoices)
	http.HandleFunc("/health", healthCheck)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
